sysauto_script.script:
// CloneShield — CloneDetector Scheduled Job
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
//
// Polls sys_clone_history every 5 minutes. When a clone is detected
// (status='In Progress' within the last 5 minutes), triggers the full
// snapshot sequence via CloneSafetyNet.snapshotAll().

(function() {
    try {
        var csn = new CloneSafetyNet();
        var result = csn.snapshotAll();
        if (result.detected) {
            gs.info('CloneShield: Clone detected. Snapshot complete. ' +
                'Event: ' + result.event_id +
                ', Artifacts: ' + result.snapshot_count);
        }
    } catch (e) {
        gs.error('CloneShield CloneDetector failed: ' + e.message);
    }
})();
